import{_ as a,o as e,c as l,a2 as o}from"./chunks/framework.DMvgf4hZ.js";const i="/toonflow/assets/skill-list.GXlB8EzH.png",n="/toonflow/assets/agent-skill.BpeYuJd_.png",s="/toonflow/assets/agent-chat.6Vv48t9w.png",u=JSON.parse('{"title":"Agent 助手","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent.md","filePath":"guide/agent.md","lastUpdated":1794745517000}'),r={name:"guide/agent.md"};function p(c,t,d,g,_,h){return e(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="agent-助手" tabindex="-1">Agent 助手 <a class="header-anchor" href="#agent-助手" aria-label="Permalink to &quot;Agent 助手&quot;">​</a></h1><p>Toonflow 的右侧对话框不是普通聊天窗口：它带着工具与技能，能直接操作画布、生成素材、推进流程。</p><p><img src="'+i+'" alt="已安装的技能列表"></p><h2 id="选择模型和技能" tabindex="-1">选择模型和技能 <a class="header-anchor" href="#选择模型和技能" aria-label="Permalink to &quot;选择模型和技能&quot;">​</a></h2><ol><li>打开项目中的 Toonflow Agent。面板关闭时，点击页面上的“Toonflow Agent”按钮重新打开。</li><li>点击输入框下方的模型名称，选择已配置的文本模型；点击书本形状的“选择技能”，选择 <code>/skill:workflow</code>（视频制作工作流）。也可以输入 <code>/</code>，从列表选择技能。</li><li>选中后，输入框会出现技能指令，直接在后面补充任务。要提供参考图，可把图片粘贴到输入区，再填写要求。</li></ol><p><img src="'+n+'" alt="选择技能与模型的输入区"></p><h2 id="说清需求-确认后继续" tabindex="-1">说清需求，确认后继续 <a class="header-anchor" href="#说清需求-确认后继续" aria-label="Permalink to &quot;说清需求，确认后继续&quot;">​</a></h2><ol><li>输入：“帮我做一支 15 秒海边日落短片，画面里有一棵椰树和一把沙滩椅，温暖安静。先给我分镜和素材清单，暂不生成图片、视频。”点击发送。</li><li>助手提问时，在卡片中填写选项并点击“提交回答”。读完方案后，可以回复：“保留三个镜头，先生成第一个镜头的图片”，逐步推进。</li><li>满意后继续说：“使用这张图片生成视频，椰树叶轻轻摇动。”需要修改时指出具体节点和内容，例如“只调暗天空，保留椰树与椅子的位置”。</li><li>点击助手顶部“历史对话”找回之前的制作记录；开始另一件事时点击“新建对话”。回到旧对话后说明从哪个镜头继续，已有素材可以接着使用。</li></ol><p><img src="'+s+'" alt="助手的新对话界面与技能指令"></p><div class="tip custom-block"><p class="custom-block-title">一次配置，长期使用</p><p>你只需要安装和登录一次，后面继续用自然语言描述创作需求即可。</p></div><h2 id="给-agent-加能力" tabindex="-1">给 Agent 加能力 <a class="header-anchor" href="#给-agent-加能力" aria-label="Permalink to &quot;给 Agent 加能力&quot;">​</a></h2><p>助手能调用的工具与技能来自插件市场，也可以自己写。装好之后：</p><ul><li>技能：在助手输入区的书本按钮中选择。</li><li>工具：由助手根据你的要求调用。</li></ul><p>扩展方式见<a href="./plugin-market.html">插件市场</a>与<a href="/toonflow/development/plugins.html">插件、技能与提供方</a>。</p>',14)])])}const f=a(r,[["render",p]]);export{u as __pageData,f as default};
